import os, sys, json
sys.path.insert(0, os.path.abspath("."))
os.environ["STAGE"] = "prod"; os.environ["DRY_RUN"] = "true"
from utils.boto import get_connections_row, org_decrypt, get_org_private_key
from utils.integrations import get_integration_file
CONN = "d64ec43a65504f939ee3ea4d9f63c89d"
row = get_connections_row(CONN)
secret = org_decrypt(row["integration_secret"], get_org_private_key(row["org_id"]))
f = get_integration_file(row["integration_name"], row["integration_type"])
i = f.Integration(connection_id=CONN, org_id=row["org_id"], integration_secret=secret,
                  connection_additional_fields=row.get("additional_fields"), customer_id=row.get("customer_id"))

for order_id in ["53110080", "53185948"]:
    print(f"\n{'='*30} ORDER {order_id} {'='*30}")
    o = i.active_ants_request(f"v3/orders/{order_id}", params={"include": "orderItems,deliveryAddress"})
    print(json.dumps(o, indent=2))
    print(f"\n{'-'*20} SHIPMENTS for order {order_id} {'-'*20}")
    s = i.active_ants_request("v3/shipments", params={
        "filter[orderId][in]": order_id, "include": "shipmentItems",
        "page[cursor]": 0, "page[size]": 100})
    print(json.dumps(s, indent=2))
    def get_orders(
        self, start, end, first_crawl, first_loop, page_token=1, sync_job_id=None
    ):
        if first_loop:
            self.set_order_maps()

        path = "orders"
        # get a full day of data if first crawl or crawl start is more than a day ago
        if first_crawl or now() - start > timedelta(days=1):
            query_end = start + timedelta(days=1)
        else:
            query_end = start + timedelta(minutes=5)
        query_end = min(query_end, end)
        query_params = {
            "page[size]": 100,
            "page[number]": page_token,
            "filter[updated_at_min]": dt_to_str(start)[:-1],
            "filter[updated_at_max]": dt_to_str(query_end)[:-1],
            "include": ORDERS_INCLUDE,
        }
        orders_rsp = self.packiyo_request(path, params=query_params)
        orders = orders_rsp["data"]
        next_token = None
        next_start = None
        if orders_rsp["links"].get("next"):
            next_token = page_token + 1
        elif query_end < end:
            next_start = query_end
        if not orders:
            return {"data": [], "next_token": next_token, "next_start": next_start}
        formatted_orders = []

        included_data = orders_rsp["included"]
        additional_data = self.get_order_query_additional_data(included_data)
        merge_data = {}
        if self.org_id in PACKIYO_MERGED_ORDER_FIELDS_ORGS:
            merge_data = self.get_order_merge_data(query_params)
        for order in orders:
            if order["attributes"]["archived_at"]:
                continue
            formatted_order = self.format_order(order, additional_data, merge_data)
            formatted_orders.append(formatted_order)

        return {
            "data": formatted_orders,
            "next_token": next_token,
            "next_start": next_start,
        }

    def get_order_merge_data(self, base_params):
        # separate sparse call so merge sideloads don't evict shipments (pylon #3556)
        params = {
            **base_params,
            "include": MERGE_INCLUDE,
            "fields[orders]": MERGE_FIELDS,
        }
        merge_rsp = self.packiyo_request("orders", params=params)
        merge_data = {}
        for order in merge_rsp["data"]:
            attributes = order["attributes"]
            relationships = order["relationships"]
            additional_fields = {}
            parent_order_id = attributes["parent_order_id"]
            if parent_order_id:
                # source order merged into a parent — bill the parent, skip this one
                additional_fields["parent_order_id"] = str(parent_order_id)
                additional_fields["merged_at"] = format_date(attributes["merged_at"])
            merged_orders = relationships["merged_orders"]["data"]
            if merged_orders:
                # parent MERGE- order — list the child orders merged into it
                merged_order_ids = []
                for child in merged_orders:
                    merged_order_ids.append(child["id"])
                additional_fields["merged_order_ids"] = merged_order_ids
            if additional_fields:
                merge_data[order["id"]] = additional_fields
        return merge_data

    def allow_orders_on_demand_sync(self):
        return True

