            rsp = i.packiyo_request("orders", params={
                "page[size]": 100, "page[number]": page,
                "filter[updated_at_min]": (end - timedelta(days=3)).strftime("%Y-%m-%dT%H:%M:%S"),
                "filter[updated_at_max]": end.strftime("%Y-%m-%dT%H:%M:%S"),
                "include": "shipments,shipments.packages",
            })
            for x in rsp.get("included", []):
                inc[(x["type"], x["id"])] = x
            if not rsp["links"].get("next"):
                break
    except Exception as e:
        print(conn, "ERR", repr(e)[:150]); continue
    multi = even = uneven = null_cost = mismatch_sum = 0
    examples = []
    for (t, sid), s in inc.items():
        if t != "shipments":
            continue
        pkgs = [inc.get(("packages", p["id"])) for p in s["relationships"]["packages"]["data"]]
        if len(pkgs) < 2 or None in pkgs:
            continue
        multi += 1
        costs = [p["attributes"]["shipping_cost"] for p in pkgs]
        if any(c is None for c in costs):
            null_cost += 1; continue
        if len(set(costs)) == 1:
            even += 1
        else:
            uneven += 1
            if len(examples) < 3:
                examples.append((sid, s["attributes"]["cost"], costs))
        if s["attributes"]["cost"] is not None and abs(sum(float(c) for c in costs) - float(s["attributes"]["cost"])) > 0.02:
            mismatch_sum += 1
            if len(examples) < 3:
                examples.append(("SUM!=COST", sid, s["attributes"]["cost"], costs))
    print(conn, f"multi={multi} even={even} uneven={uneven} null_pkg_cost={null_cost} sum_ne_cost={mismatch_sum}", examples)
